<script lang="ts">
 import { enhance, type SubmitFunction } from '$app/forms';
 import '../../../../app.css';import '#lib/v2/styles/v2.css';import imgLogo from '#lib/assets/images/logo.png';import{ArrowLeft,ShieldCheck,CheckCircle2,AlertCircle,Eye,EyeOff,KeyRound}from'@lucide/svelte';import type{PageProps}from'./$types';let{data,form}:PageProps=$props();let code=$state('');let password=$state('');let confirm=$state('');let show=$state(false);let state=$state<'idle'|'checking'|'valid'|'invalid'>('idle');let codeError=$state('');let busy=$state(false);let resending=$state(false);let timer:ReturnType<typeof setTimeout>;
 const handleReset: SubmitFunction = () => { busy = true; return async ({ update }) => { await update(); busy = false; }; };
 const handleResend: SubmitFunction = () => { resending = true; return async ({ update }) => { await update(); resending = false; }; };
function validate(value:string){clearTimeout(timer);if(value.length!==6){state='idle';codeError='';return;}state='checking';const fd=new FormData();fd.set('code',value);timer=setTimeout(async()=>{try{const r=await fetch('?/validate',{method:'POST',headers:{accept:'application/json','x-sveltekit-action':'true'},body:fd});const j=await r.json();if(code!==value)return;if(r.ok&&j?.data?.valid){state='valid';codeError='';}else{state='invalid';codeError=j?.data?.error??'Invalid code.';}}catch{state='invalid';codeError='Could not validate code.';}},250);}
const rules=[{label:'At least 12 characters',ok:()=>password.length>=12},{label:'Uppercase and lowercase letters',ok:()=>/[A-Z]/.test(password)&&/[a-z]/.test(password)},{label:'At least one number',ok:()=>/\d/.test(password)},{label:'At least one symbol',ok:()=>/[^A-Za-z0-9]/.test(password)}];
</script>
<svelte:head><title>Set a new password · Godan CRM</title></svelte:head>
<div class="v2-root v2-auth v2-auth-modern v2-auth-code-page"><div class="v2-auth-code-glow"></div><div class="v2-auth-box v2-auth-box-modern v2-auth-code-box"><a href="/" class="v2-auth-brand"><img src={imgLogo} alt=""/><b>Godan CRM</b></a><div class="v2-auth-card v2-auth-card-modern v2-auth-code-card">
<div class="v2-auth-head v2-auth-head-modern"><div class="v2-auth-card-kicker">ACCOUNT SECURITY</div><h1>Create a stronger password</h1><p>If this email belongs to an active account, a reset OTP will arrive at <strong>{data.email}</strong>. Verify it, then set your new login password.</p></div>
{#if form?.error}<div class="v2-auth-note v2-auth-note-bad" role="alert">{form.error}</div>{/if}{#if form?.message}<div class="v2-auth-note v2-auth-note-ok" role="status">{form.message}</div>{/if}
<form method="POST" use:enhance={handleReset} class="v2-auth-form"><div class="v2-auth-field"><label for="code">Enter OTP</label><div class="v2-auth-password-wrap"><input id="code" name="code" class="v2-input v2-auth-otp-input" class:v2-auth-otp-invalid={state==='invalid'} class:v2-auth-otp-valid={state==='valid'} bind:value={code} oninput={()=>{code=code.replace(/\D/g,'').slice(0,6);validate(code)}} inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000" required/>{#if state==='valid'}<CheckCircle2 class="v2-auth-code-valid-icon" size={19}/>{:else if state==='invalid'}<AlertCircle class="v2-auth-code-invalid-icon" size={19}/>{/if}</div>{#if state==='checking'}<small class="v2-auth-help">Checking code…</small>{:else if state==='valid'}<small class="v2-auth-help v2-auth-valid-text">Code verified.</small>{:else if state==='invalid'}<small class="v2-auth-help v2-auth-error-text">{codeError}</small>{:else}<small class="v2-auth-help">Enter or paste the six-digit code. It is checked automatically.</small>{/if}</div>
<div class="v2-auth-field"><label for="password">Setup new login password</label><div class="v2-auth-password-wrap"><KeyRound size={16} class="v2-auth-input-icon"/><input id="password" name="password" class="v2-input" type={show?'text':'password'} bind:value={password} autocomplete="new-password" placeholder="Create a strong password" required/><button type="button" class="v2-auth-password-toggle" onclick={()=>show=!show} aria-label={show?'Hide password':'Show password'}>{#if show}<EyeOff size={17}/>{:else}<Eye size={17}/>{/if}</button></div><ul class="v2-auth-password-rules">{#each rules as rule (rule.label)}<li class:rule-ok={rule.ok()}><CheckCircle2 size={14}/>{rule.label}</li>{/each}</ul></div>
<div class="v2-auth-field"><label for="confirm_password">Repeat new password</label><input id="confirm_password" name="confirm_password" class="v2-input" type={show?'text':'password'} bind:value={confirm} autocomplete="new-password" placeholder="Enter it again" required/>{#if confirm&&confirm!==password}<small class="v2-auth-help v2-auth-error-text">Passwords do not match.</small>{:else if confirm&&confirm===password}<small class="v2-auth-help v2-auth-valid-text">Passwords match.</small>{/if}</div>
<button class="v2-btn v2-btn-primary v2-btn-block v2-auth-submit" disabled={busy||state!=='valid'||!rules.every(r=>r.ok())||confirm!==password}>{busy?'Updating password…':'Reset password securely'}</button></form>
<div class="v2-auth-resend"><span>Code expired or missing?</span><form method="POST" action="?/resend" use:enhance={handleResend}><button disabled={resending}>{resending?'Sending…':'Request new OTP'}</button></form></div><div class="v2-auth-security-note"><ShieldCheck size={16}/><span>Successful reset invalidates outstanding one-time codes.</span></div></div><a href="/login/forgot-password" class="v2-auth-back"><ArrowLeft size={15}/> Back to recovery options</a></div></div>
